public sealed class OrderService(AppDbContext db)          // injected scoped context
{
    public Task<Order?> FindAsync(Guid id, CancellationToken ct) =>
        db.Orders.FirstOrDefaultAsync(o => o.Id == id, ct);   // DbSet is the repository

    public async Task AddAsync(Order order, CancellationToken ct)
    {
        db.Orders.Add(order);
        await db.SaveChangesAsync(ct);                        // Unit of Work flush
    }
}

