public interface IOrderRepository : IRepository<Order>        // domain layer
{
    Task<Order?> FindAsync(Guid id, CancellationToken ct);
    Task<IReadOnlyList<Order>> FindOverdueAsync(DateOnly on, CancellationToken ct);
}

public sealed class OrderRepository(AppDbContext db) : IOrderRepository
{
    public Task<Order?> FindAsync(Guid id, CancellationToken ct) =>
        db.Orders.FirstOrDefaultAsync(o => o.Id == id, ct);
    public void Add(Order order) => db.Orders.Add(order);    // no SaveChanges here
}
